#!/usr/bin/env python3
"""Build the existing static PlayCall site; public content only, no dependencies."""
from pathlib import Path
from urllib.parse import urlsplit
import html,json,re
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'dist';OUT.mkdir(exist_ok=True)
cfg=json.loads((ROOT/'content/release.json').read_text());wait=json.loads((ROOT/'content/waitlist.json').read_text());policy=json.loads((ROOT/'content/policy.json').read_text());e=html.escape
draft=not (cfg.get('publicationApproved') and cfg.get('websitePrivacyApproved'))
base=(cfg.get('siteURL') or '').rstrip('/')+'/' if cfg.get('siteURL') else None
if base and (urlsplit(base).scheme!='https' or urlsplit(base).query or urlsplit(base).fragment):raise ValueError('siteURL must be a clean HTTPS base URL')
nav=[('privacy.html','Privacy Policy'),('support.html','Support'),('league-rules.html','League Rules & Equipment')]
def external(url,label):return f'<a href="{e(url,quote=True)}" rel="noreferrer">{e(label)} <span aria-hidden="true">↗</span></a>'
def introduction(kicker,title,summary):return f'<div class="page-intro container"><p class="eyebrow">{e(kicker)}</p><h1>{e(title)}</h1><p class="lead">{e(summary)}</p></div>'
def page(filename,title,description,body,hidden=False):
 links=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==filename else '')+f'>{label}</a>' for f,label in nav)
 robots='<meta name="robots" content="noindex,nofollow">' if draft or hidden else '<meta name="robots" content="index,follow">'
 canonical=f'<link rel="canonical" href="{e(base+("" if filename=="index.html" else filename))}"><meta property="og:url" content="{e(base+("" if filename=="index.html" else filename))}">' if base and not hidden else ''
 image=(base or '')+'assets/social-preview.png'
 banner='<div class="review-banner">Local review preview · Waitlist testing and policy review pending</div>' if draft else ''
 text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — PlayCall</title><meta name="description" content="{e(description)}"><meta name="referrer" content="no-referrer"><meta name="color-scheme" content="dark">{robots}{canonical}<meta property="og:type" content="website"><meta property="og:site_name" content="PlayCall"><meta property="og:title" content="{e(title)} — PlayCall"><meta property="og:description" content="{e(description)}"><meta property="og:image" content="{e(image)}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="PlayCall: Your game. Your calls. Coming to iPhone."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)} — PlayCall"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{e(image)}"><meta name="theme-color" content="#090b0e"><link rel="icon" href="assets/favicon.png" type="image/png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><link rel="stylesheet" href="assets/styles.css"></head><body><a class="skip-link" href="#main">Skip to content</a>{banner}<header class="site-header container"><a class="brand" href="index.html" aria-label="PlayCall home"><img src="assets/wordmark.png" width="1141" height="188" alt="PlayCall"></a><nav aria-label="Main navigation"><a class="desktop-nav" href="index.html#how-it-works">How it works</a><a class="desktop-nav" href="index.html#app-preview">The app</a><a class="desktop-nav" href="index.html#faq">FAQ</a><a class="nav-cta" href="index.html#waitlist">Join the waitlist <span aria-hidden="true">↗</span></a></nav></header><main id="main" tabindex="-1">{body}</main><footer class="site-footer container"><div><a href="index.html" aria-label="PlayCall home"><img src="assets/wordmark.png" width="1141" height="188" alt="PlayCall"></a><p>Your game. Your calls.<br>Coming to iPhone.</p></div><nav aria-label="Footer navigation">{links}<a href="mailto:{e(cfg['supportEmail'])}">Contact</a></nav><p class="footer-note">Confirm your competition’s communication and equipment rules before use. Bluetooth compatibility is not competition approval.</p></footer></body></html>'''
 (OUT/filename).write_text(text)

def waitlist():
 consent='<p class="consent">By signing up, you agree to receive PlayCall launch announcements and relevant beta-testing opportunities. Unsubscribe at any time. <a href="privacy.html#website-waitlist">Privacy &amp; waitlist data</a>.</p>'
 if wait['mode']=='embed':
  embed=(ROOT/'content/mailerlite-form.html').read_text()
  if '<form' not in embed and 'ml-embedded' not in embed:raise ValueError('Paste an official MailerLite embed before enabling embed mode')
  if not cfg.get('providerFormReviewed'):raise ValueError('Review the actual public provider embed before enabling it')
  return '<div class="provider-form"><p class="fine-print">Load the email form to connect to MailerLite and Google reCAPTCHA. Their form and anti-spam processing apply.</p><p style="margin-top:14px"><button class="button primary" type="button" data-load-waitlist aria-controls="mailerlite-mount">Load email signup ↗</button></p><p class="fine-print" id="waitlist-status" role="status" aria-live="polite"></p><p class="waitlist-error" id="waitlist-errors" role="alert" aria-atomic="true"></p><div id="mailerlite-mount"></div><template id="mailerlite-template">'+embed+'</template><p class="fine-print" style="margin-top:12px"><a href="'+e(wait['hostedFormURL'],quote=True)+'" rel="noreferrer">Open signup on MailerLite instead ↗</a></p></div>'+consent+'<script src="assets/waitlist.js" defer></script>' 
 if wait['mode']=='hosted':
  url=wait.get('hostedFormURL') or '';u=urlsplit(url)
  if u.scheme!='https' or not u.hostname or not cfg.get('providerFormReviewed'):raise ValueError('A reviewed HTTPS MailerLite form URL is required')
  return '<p style="margin-top:18px"><a class="button primary" href="'+e(url,quote=True)+'" rel="noreferrer">Join the waitlist ↗</a></p>'+consent+'<p class="fine-print">Email signup opens securely on MailerLite.</p>'
 if wait['mode']!='unconfigured':raise ValueError('Unknown waitlist mode')
 return '<div class="waitlist-pending" role="status"><strong>Waitlist signup is being connected.</strong><p>Email collection is not open yet. Please check back soon.</p><a href="mailto:'+e(cfg['supportEmail'])+'">Have a question? Contact PlayCall ↗</a></div>'
page('index.html','Your game. Your calls.','Coming to iPhone: live coach-to-catcher communication with compatible microphones, Bluetooth headphones and hold-to-talk control.',(ROOT/'content/home.html').read_text().replace('{{WAITLIST}}',waitlist()))
for name,title,desc in [('support','Support','Setup guidance, troubleshooting and the official PlayCall support contact.'),('league-rules','League Rules & Equipment','Check current competition rules and equipment eligibility. Bluetooth compatibility is not official approval.')]:
 page(name+'.html',title,desc,(ROOT/f'content/{name}.html').read_text())
privacy=introduction('Privacy & data','Your voice. Your data.','How PlayCall handles live audio, local settings, Apple services, support and the optional prelaunch waitlist.')
notice='Review draft. Public launch is on hold while a subscriber-facing postal address is arranged. Provider verification and the publication effective date remain pending.' if draft else 'Effective '+str(cfg['effectiveDate'])
privacy+='<div class="container legal-layout"><aside class="policy-summary"><p class="eyebrow">In this policy</p><p><a href="#website-waitlist">Website &amp; waitlist</a></p><p><a href="#app-data">iPhone app</a></p><p><a href="#contact">Contact &amp; updates</a></p><p class="small">'+e(notice)+'</p></aside><article class="legal-copy">'
if draft:privacy+='<div class="notice"><strong>Privacy policy review draft</strong><p>'+e(notice)+'</p></div>'
privacy+='''<section id="website-waitlist"><h2>Website and prelaunch waitlist</h2><p>PlayCall’s website is prepared for GitHub Pages hosting. GitHub processes ordinary request information, such as IP addresses and browser information, to provide and secure its services under its own privacy terms. The website does not store subscriber emails in its source repository, browser storage or a PlayCall server.</p><p>The website has no authored advertising or analytics tags. Standard campaign links may contain UTM parameters; the site does not save them or use them to create a visitor profile. Hosting and email providers have their own processing practices.</p></section>'''
if wait['mode']=='unconfigured':privacy+='<section><h2>Signup is not active in this preview</h2><p>No MailerLite form or script is loaded in this preview and no email addresses are collected by it. The following describes the proposed waitlist handling, which must be operationally verified before public signup launch.</p></section>'
privacy+='''<section><h2>Email signup and consent</h2><p>The optional PlayCall Prelaunch Waitlist asks for your email address only. MailerLite is the configured subscription-management provider. Signup is for PlayCall launch announcements and relevant beta-testing opportunities, not unrelated mailing lists or guaranteed beta access. The configured flow sends a confirmation email and requires you to confirm before becoming an active subscriber. A visit to a confirmation page alone does not establish subscriber status.</p><p>MailerLite processes subscriber details, subscription status and consent/confirmation records, and technical information used for delivery and abuse prevention. The configured form uses a visible consent checkbox, double opt-in and Google reCAPTCHA. Test renders contacted MailerLite delivery, font and form endpoints plus Google reCAPTCHA resources. The final public-domain and outgoing-message behavior must still be checked before launch. The developer can access subscriber records through MailerLite; this is separate from the app’s local live-audio processing.</p></section>
<section><h2>Cookies, spam protection and email measurement</h2><p>MailerLite forms can use cookies or similar storage. If an embedded form or reCAPTCHA is enabled, its providers receive the request information needed to operate the form or challenge. If signup instead opens on a MailerLite-hosted page, that page’s provider processing applies after you follow the link. This preview makes no promise that the final provider integration is cookie-free.</p><p>The current integration waits for your intentional form-load action before requesting MailerLite and Google resources. The reviewed providers are MailerLite and Google reCAPTCHA. In clean test browsers, no cookies or local/session storage keys were observed immediately after rendering the form; that observation does not cover CAPTCHA completion, submission, email clicks, different browsers or future provider changes. Apply any required consent controls for the final configuration. No surveys, advertising pixels or email open/click measurement are requested for this waitlist; default campaign and automation open tracking has been disabled, and Google Analytics defaults are off. Provider-generated messages and click measurement still require verification. MailerLite may process service, delivery, bounce and unsubscribe records even if optional campaign tracking is off.</p></section>
<section><h2>Waitlist retention and deletion</h2><p>The developer-approved schedule is to remove unconfirmed signup records after 30 days; retain active prelaunch subscriptions until you unsubscribe or request deletion, 12 months after confirmation, or 180 days after the public app launch, whichever happens first. Any longer-running product-news list would require a separate choice. No launch date has been set. The developer would review this schedule monthly and remove stale lists if the launch is abandoned.</p><p>Use the unsubscribe link in a waitlist email to stop messages, or contact playcall.support@gmail.com. Unsubscribing and deleting records are different actions. Minimal suppression and consent records may need to remain to honor unsubscribe requests or applicable obligations, subject to provider capabilities and a reviewed retention schedule. Provider backups and independent downloaded copies may have separate deletion timelines. The active-subscriber rule is separate from support-report retention.</p></section>'''
privacy+='<section><h2>Website service providers</h2><p>'+external('https://www.mailerlite.com/legal/privacy-policy','MailerLite privacy policy')+' · '+external('https://www.mailerlite.com/help/which-cookies-are-used-by-mailerlite-forms','MailerLite form cookies')+' · '+external('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement','GitHub privacy statement')+'</p></section><section id="app-data"><h2>The PlayCall iPhone app</h2><p>The app’s local audio path is separate from this optional website waitlist. Signing up is not required to use the app.</p></section>'
for s in policy:
 if s['title']=='Contact and policy updates':continue
 privacy+='<section><h2>'+e(s['title'])+'</h2><p>'+e(s['text'])+'</p></section>'
contact=('Provider: '+cfg['providerName']+'. Effective date will be set at publication.') if draft else 'Provider: '+str(cfg['providerName'])+'. Effective: '+str(cfg['effectiveDate'])+'.'
privacy+='<section id="contact"><h2>Contact and policy updates</h2><p>Support and privacy: <a href="mailto:'+e(cfg['privacyContact'])+'">'+e(cfg['privacyContact'])+'</a>. '+e(contact)+' Approved policy updates will identify a new effective date and be published before changed data practices take effect. Material changes to the purpose of waitlist messages require a new choice.</p></section></article></div>'
page('privacy.html','Privacy Policy','PlayCall app audio, local preferences, Apple purchases, support records and website waitlist handling.',privacy)
for name,heading,lead,extra,symbol in [
 ('check-your-email','You’re almost on the list.','Check your email to confirm your subscription.','Open the confirmation link sent by MailerLite. If you do not see it, check spam or promotions. You are not an active waitlist member until the provider records confirmation.','✉'),
 ('confirmed','You’re on the list.','We’ll let you know when PlayCall is ready.','This is the destination after MailerLite confirms your subscription. Visiting this page directly does not add you to the waitlist or verify your status. You can unsubscribe from any waitlist email.','✓')]:
 body='<section class="container success-layout"><div class="success-symbol" aria-hidden="true">'+symbol+'</div><p class="eyebrow">PlayCall prelaunch waitlist</p><h1>'+heading+'</h1><p class="lead">'+lead+'</p><p>'+extra+'</p><a class="button secondary" href="index.html">Back to PlayCall</a></section>'
 page(name+'.html','Confirm your email' if name=='check-your-email' else 'Waitlist confirmation','PlayCall waitlist email confirmation information.',body,hidden=True)
(OUT/'robots.txt').write_text('User-agent: *\n'+('Disallow: /\n' if draft else 'Allow: /\nDisallow: /check-your-email.html\nDisallow: /confirmed.html\n')+(f'Sitemap: {base}sitemap.xml\n' if base and not draft else ''))
if base and not draft:
 urls=['','privacy.html','support.html','league-rules.html']
 (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(base+x)+'</loc></url>' for x in urls)+'</urlset>')
else:(OUT/'sitemap.xml').unlink(missing_ok=True)
if cfg.get('customDomain'):(OUT/'CNAME').write_text(cfg['customDomain'].strip()+'\n')
else:(OUT/'CNAME').unlink(missing_ok=True)
print('Built six static pages; waitlist mode:',wait['mode'],'public policy approved:',not draft)
